import base64,json,html,subprocess
from pathlib import Path
root=Path(__file__).parent
meta=json.loads((root/'results.json').read_text());cards=[]
for result in meta['results']:
 voice=result['voice'];mp3=root/'audio'/(voice+'.mp3')
 subprocess.run(['ffmpeg','-v','error','-y','-i',str(root/'audio'/(voice+'.wav')),'-codec:a','libmp3lame','-b:a','96k',str(mp3)],check=True)
 src='data:audio/mpeg;base64,'+base64.b64encode(mp3.read_bytes()).decode()
 cards.append(f'<article><span class="tag">{"CURRENT BASELINE" if voice=="alba" else "NEW PRESET CANDIDATE"}</span><h2>{voice.title()}</h2><p>{result["duration_seconds"]:.1f} seconds · English narration</p><audio controls preload="metadata" aria-label="Listen to {voice.title()}" src="{src}"></audio></article>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pocket voice audition</title><style>*{box-sizing:border-box}body{margin:0;background:#111517;color:#f1f3ed;font:16px/1.6 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:48px 24px}h1{font-size:clamp(32px,6vw,58px);line-height:1.1;margin:10px 0 20px}p{color:#b9c4c5}.tag{font-size:11px;letter-spacing:.12em;color:#96d5bc}blockquote{margin:24px 0;padding:20px 24px;border-left:3px solid #96d5bc;background:#1b2225}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}article{background:#1b2225;padding:22px;border:1px solid #354045;border-radius:14px;min-width:0}h2{margin:8px 0}audio{width:100%;margin-top:8px}a{color:#96d5bc}footer{margin-top:32px;font-size:14px}</style><main><span class="tag">POCKET TTS · VOICE AUDITION</span><h1>Five new voices.<br>One familiar baseline.</h1><p>All six clips are generated by our current CPU Pocket model from the same passage. Alba is the existing baseline. The other voices are audition candidates and have not been added to the Listen player.</p><blockquote>'''+html.escape(meta['text'])+'''</blockquote><section class="grid">'''+''.join(cards)+'''</section><footer><p>Compare pronunciation, pacing, and how comfortable each voice is to follow. Different clip lengths reflect each voice's delivery. These English samples do not test other languages.</p><p>Model: English 2026-04, int8, timestamped Pocket build. <a href="https://huggingface.co/kyutai/pocket-tts-without-voice-cloning">Official ungated voice files</a> · <a href="https://huggingface.co/kyutai/tts-voices">Voice sources and licensing</a></p></footer></main><script>document.addEventListener('play',function(e){if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(function(a){if(a!==e.target)a.pause()})},true)</script></html>'''
(root/'audition.html').write_text(page)
print('HTML bytes:',len(page.encode()))
